{"file_path":"src/diff.js","content":"/**
 * Longest common subsequence over whole lines, and the changes it implies.
 */

/**
 * Matches of the longest common subsequence of `base` and `side`, as pairs of
 * indices. Ties are broken towards matches that come earliest: at each step a
 * match is taken when the current lines are equal, and otherwise the side whose
 * remaining subsequence is at least as long as the other's advances, with the
 * base preferred when the two are equal.
 */
export function lcsMatches(base, side) {
  const n = base.length
  const m = side.length
  // table[i][j] = length of the lcs of base[i..] and side[j..]
  const table = []
  for (let i = 0; i <= n; i += 1) table.push(new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i -= 1) {
    for (let j = m - 1; j >= 0; j -= 1) {
      table[i][j] =
        base[i] === side[j]
          ? table[i + 1][j + 1] + 1
          : Math.max(table[i + 1][j], table[i][j + 1])
    }
  }
  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i += 1
      j += 1
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return matches
}

/**
 * The stretches the subsequence does not cover, each a run of base lines
 * replaced by a run of the side's lines.
 */
export function changes(base, side) {
  const matches = lcsMatches(base, side)
  const result = []
  let baseAt = 0
  let sideAt = 0
  const stops = matches.concat([[base.length, side.length]])
  for (const [i, j] of stops) {
    if (i > baseAt || j > sideAt) {
      result.push({ baseStart: baseAt, baseEnd: i, start: sideAt, end: j })
    }
    baseAt = i + 1
    sideAt = j + 1
  }
  return result
}
"}

