{"file_path":"src/merge.js","content":"/**
 * The three-way merge itself: regions of the base, and how each resolves.
 */

import { changes } from './diff.js'

const equal = (a, b) => a.length === b.length && a.every((line, i) => line === b[i])

/**
 * The regions of the merge, in base order. A stable region is
 * `{ kind: 'stable', lines }`; a changed one carries the three candidate runs
 * and its resolution.
 */
export function regionsOf(mine, base, theirs) {
  const all = changes(base, mine)
    .map(change => ({ ...change, side: 'mine' }))
    .concat(changes(base, theirs).map(change => ({ ...change, side: 'theirs' })))
  all.sort((a, b) => a.baseStart - b.baseStart || (a.side === b.side ? 0 : a.side === 'mine' ? -1 : 1))

  const groups = []
  let at = 0
  while (at < all.length) {
    const group = [all[at]]
    let end = all[at].baseEnd
    at += 1
    while (at < all.length && all[at].baseStart <= end) {
      end = Math.max(end, all[at].baseEnd)
      group.push(all[at])
      at += 1
    }
    groups.push({ start: group[0].baseStart, end, group })
  }

  const documents = { mine, theirs }
  const regions = []
  let baseAt = 0
  for (const { start, end, group } of groups) {
    if (start > baseAt) regions.push({ kind: 'stable', lines: base.slice(baseAt, start) })
    const baseLines = base.slice(start, end)
    const runs = {}
    for (const side of ['mine', 'theirs']) {
      const own = group.filter(change => change.side === side)
      if (own.length === 0) {
        runs[side] = baseLines.slice()
        continue
      }
      const ownBaseStart = Math.min(...own.map(change => change.baseStart))
      const ownBaseEnd = Math.max(...own.map(change => change.baseEnd))
      const from = Math.min(...own.map(change => change.start)) - (ownBaseStart - start)
      const to = Math.max(...own.map(change => change.end)) + (end - ownBaseEnd)
      runs[side] = documents[side].slice(from, to)
    }
    regions.push({ ...resolve(runs.mine, baseLines, runs.theirs) })
    baseAt = end
  }
  if (baseAt < base.length) regions.push({ kind: 'stable', lines: base.slice(baseAt) })
  return regions
}

function resolve(mine, base, theirs) {
  if (equal(mine, theirs)) return { kind: 'both', lines: mine, mine, base, theirs }
  if (equal(mine, base)) return { kind: 'theirs', lines: theirs, mine, base, theirs }
  if (equal(theirs, base)) return { kind: 'mine', lines: mine, mine, base, theirs }
  return { kind: 'conflict', lines: null, mine, base, theirs }
}
"}

